import pytest
from unittest.mock import MagicMock, patch

# Assuming the existence of modules: prescription_system, chemist, lab, admin, patient, and system_api
from prescription_system import PrescriptionSystem
from chemist import Chemist
from lab import Lab
from admin import Admin
from patient import Patient
from system_api import SystemAPI

@pytest.fixture
def patient():
    return Patient()

@pytest.fixture
def chemist():
    return Chemist()

@pytest extration
def lab():
    return Lab()

@pytest.fixture
def admin():
    return Admin()

@pytest.fixture
def system_api():
    return SystemAPI()

@pytest.fixture
def mock_patient_data():
    return {"name": "John Doe", "age": 30, "medical_history": "None"}

@pytest.fixture
def mock_chemist_data():
    return {"chemist_id": 1, "location": "Nearest Chemist"}

@pytest.fixture
def mock_lab_data():
    return {"lab_id": 1, "location": "Nearest Lab"}

@pytest.fixture
def mock_admin_data():
    return {"admin_id": 1, "specialities": ["Cardiology", "Neurology"], "doctors": [{"doctor_id": 1, "name": "Dr. Smith"}, {"doctor_id": 2, "name": "Dr. Jones"}]

# Test Case 1: Prescription is received by patient
@pytest.mark.positive
def test_prescription_received_by_patient(patient, system_api):
    with patch('prescription_system.get_prescription', return_value=mock_patient_data()) as mock_get_prescription, patch('system_api.display_prescription', autospec=True):
        system_api.display_prescription()
        mock_get_prescription.assert_called_once_with(patient)

# Test Case 2: Chemist provides medicines to the patient via offline delivery
@pytest.mark.positive
def test_chemist_delivers_medicines(chemist, patient):
    chemist.deliver_medicine(patient)
    chemist.offline_delivery.assert_called_once_with()

# Test Case 3: Lab uses the prescription to collect specimen and make delivery of lab reports
@pytest.mark.positive
def test_lab_uses_prescription_for_specimen_and_report(lab, patient):
    lab.collect_specimen(patient)
    lab.make_report().assert_called_once_with()

# Test Case 4: Confidentiality of patient information for Chemists and Labs
@pytest.mark.negative
def test_chemist_accesses_patient_info_without_permission(chemist, patient):
    with pytest.raises(PermissionError):
        chemist.access_patient_info(patient)

    with pytest.raises(PermissionError):
        lab.access_patient_info(patient)

# Test Case 5: Admin populates speciality database
@pytest.mark.positive
def test_admin_populates_speciality_database(admin, mock_admin_data):
    admin.populate_speciality_database()
    assert admin.speciality_database == mock_admin_data["specialities"]

# Test Case 6: Admin links specialities to doctors
@pytest.mark.positive
def test_admin_links_specialities_to_doctors(admin, mock_admin_data):
    admin.link_specialities_to_doctors()
    assert admin.doctors == {doctor["doctor_id"] for doctor in mock_admin_data["doctors"]}

# Test Case 7: Admin uses lab and chemist information to populate databases
@pytest.mark.positive
def test_admin_populates_databases_from_info(admin, mock_chemist_data, mock_lab_data):
    admin.populate_databases(mock_chemist_data, mock_lab_data)
    # Assuming methods to check database population exist
    assert chemist.database_updated()
    assert lab.database_updated()

# Test Case 8: Patient registers into the system
@pytest.mark.positive
def test_patient_registers(patient):
    patient.register()
    assert patient.registered

# Test Case 9: Chemist and Lab only see necessary information
@pytest.mark.negative
def test_unauthorized_access_to_full_patient_info(chemist, patient):
    with pytest.raises(PermissionError):
        chemist.access_full_patient_info(patient)

    with pytest.raises(PermissionError):
        lab.access_full_patient_info(patient)

